using System.Reflection;
using ModelContextProtocol.Protocol;

var t = typeof(TextContentBlock);
Console.WriteLine("--- TextContentBlock ---");
foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance))
    Console.WriteLine($"  {p.PropertyType.Name} {p.Name}");
Console.WriteLine($"  Base: {t.BaseType?.Name}");

// Check ContentBlock
Console.WriteLine("\n--- ContentBlock ---");
var cb = typeof(ContentBlock);
foreach (var p in cb.GetProperties(BindingFlags.Public | BindingFlags.Instance))
    Console.WriteLine($"  {p.PropertyType.Name} {p.Name}");

// Check static factory or constructors
Console.WriteLine("\n--- ContentBlock constructors ---");
foreach (var c in cb.GetConstructors()) {
    var pars = string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
    Console.WriteLine($"  ({pars})");
}

// Check implicit operators
Console.WriteLine("\n--- ContentBlock implicit operators ---");
foreach (var m in cb.GetMethods(BindingFlags.Public | BindingFlags.Static).Where(m => m.Name.Contains("Implicit") || m.Name.Contains("op_")))
    Console.WriteLine($"  {m.ReturnType.Name} {m.Name}({string.Join(", ", m.GetParameters().Select(p => p.ParameterType.Name))})");

// TextContentBlock constructors
Console.WriteLine("\n--- TextContentBlock constructors ---");
foreach (var c in t.GetConstructors()) {
    var pars = string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"));
    Console.WriteLine($"  ({pars})");
}
